use verus::prelude::*;

// We treat a matrix as a Vec of Vecs.
type Matrix<T> = Vec<Vec<T>>;

#[requires(a.len() > 0)]
#[requires(shape.len() == 2)]
#[requires((shape[0] as usize) > 0 && (shape[1] as usize) > 0)]
#[requires(a.len() == shape[0] as usize || a.len() == shape[1] as usize)]
#[ensures(ret.len() == shape[0] as usize)]
#[ensures(forall(|i: usize| i < shape[0] as usize ==> ret[i].len() == shape[1] as usize))]
#[ensures(
    forall(|i: usize, j: usize| 
        i < shape[0] as usize && j < shape[1] as usize ==>
        if a.len() == shape[0] as usize {
            // column‐vector broadcasting
            ret[i][j] == a[i]
        } else {
            // row‐vector broadcasting
            ret[i][j] == a[j]
        }
    )
)]
fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Convert the shape entries to usize for indexing and sizes.
    let R: usize = shape[0] as usize;
    let C: usize = shape[1] as usize;
    // We'll build the matrix row by row.
    let mut ret: Matrix<i8> = Vec::new();
    // Loop over rows.
    let mut i: usize = 0;
    while i < R {
        invariant(i <= R);
        invariant(ret.len() == i);
        decreases(R - i);

        // Decide whether we're broadcasting as a column or row vector.
        if a.len() == R {
            // Column‐vector broadcasting: each row i is a[i] repeated C times.
            let mut row: Vec<i8> = Vec::new();
            let mut j: usize = 0;
            while j < C {
                invariant(j <= C);
                invariant(row.len() == j);
                decreases(C - j);

                row.push(a[i]);
                j += 1;
            }
            ret.push(row);
        } else {
            // Row‐vector broadcasting: each row is the entire array a (of length C).
            // We know a.len() == C here.
            assert(a.len() == C);
            let mut row: Vec<i8> = Vec::new();
            let mut j: usize = 0;
            while j < C {
                invariant(j <= C);
                invariant(row.len() == j);
                decreases(C - j);

                row.push(a[j]);
                j += 1;
            }
            ret.push(row);
        }

        i += 1;
    }

    ret
}

#[proof]
fn test_broadcast_column() {
    let a = vec![1i8, 2, 3];
    let shape = vec![3u8, 4u8];
    let m = broadcast(a.clone(), shape.clone());
    // Should be 3×4, each row i constant a[i].
    assert(m.len() == 3);
    assert(m[0].len() == 4);
    assert(m[1].len() == 4);
    assert(m[2].len() == 4);
    assert(m[0] == vec![1, 1, 1, 1]);
    assert(m[1] == vec![2, 2, 2, 2]);
    assert(m[2] == vec![3, 3, 3, 3]);
}

#[proof]
